import{_ as a,o as i,c as o,a5 as s}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Contratos Cloud, sincronización y revisión","description":"","frontmatter":{"title":"Contratos Cloud, sincronización y revisión","docId":"developer.cloud","translationKey":"developer.cloud","locale":"es","audience":"developer","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"06ae46545d1366d4f456c78a0e6583ea0338afbd496467e4d25b3abe1a5430fb","translationRevision":"0713578c1bd68eec313961653afc6d68eaaa387e0cfb83da739808ae62b926b6","order":180},"headers":[],"relativePath":"es/developer/cloud.md","filePath":"es/developer/cloud.md","lastUpdated":1794611623000}'),r={name:"es/developer/cloud.md"};function n(t,e,c,d,l,p){return i(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="cloud-contracts-synchronization-and-review" tabindex="-1">Contratos Cloud, sincronización y revisión <a class="header-anchor" href="#cloud-contracts-synchronization-and-review" aria-label="Permalink to &quot;Contratos Cloud, sincronización y revisión {#cloud-contracts-synchronization-and-review}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo y requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo y requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Desarrolla configuración de cuenta y catálogo contra la instancia Cloud aprovisionada. El funcionamiento exclusivamente local sigue siendo válido. Para trabajo autenticado, utiliza cuenta/backend de prueba y entrega nativa de sesión; esta documentación no demuestra aceptación del token de producción ni de dos dispositivos.</p><p>El propietario verificado es <a href="https://github.com/nglmercer/RemakeBackend" target="_blank" rel="noreferrer">nglmercer/RemakeBackend</a>, con <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V2.md" target="_blank" rel="noreferrer">contratos v2</a> y <a href="https://github.com/nglmercer/RemakeBackend/blob/master/docs/CLOUD-API-V3.md" target="_blank" rel="noreferrer">superficies v3</a> adicionales. Los tipos portables y transporte del backend están representados localmente en <code>crates/cloud-contracts</code> y <code>crates/cloud-client</code>. Durabilidad y autenticación del escritorio siguen siendo responsabilidad del host.</p><h2 id="gate-and-stage-operations" tabindex="-1">Comprobar capacidades y preparar operaciones <a class="header-anchor" href="#gate-and-stage-operations" aria-label="Permalink to &quot;Comprobar capacidades y preparar operaciones {#gate-and-stage-operations}&quot;">​</a></h2><ol><li>Descubre métodos nativos con <code>rpc.discover</code>; un host antiguo puede conservar vistas heredadas.</li><li>Deja que el host consulte <code>/api/v2/capabilities</code> antes del endpoint protegido. No conviertas una capacidad del servidor en una bandera fija del navegador.</li><li>Usa el origen aprovisionado por el operador. Las versiones de distribución no aceptan sustituciones arbitrarias en ejecución.</li><li>Previsualiza migración y conflictos, conserva bases congeladas y escrituras inciertas, y envía únicamente lo revisado.</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> discover</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sync.v2.migrate</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schema</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> globals.typed.replace</span></span></code></pre></div><p>Estas órdenes inspeccionan esquemas; no migran cuentas ni guardan variables.</p><h2 id="current-implementation" tabindex="-1">Implementación actual <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Implementación actual {#current-implementation}&quot;">​</a></h2><p>V2 tiene estado/almacén/coordinador nativos, migración v1 protegida, revisión de conflictos, reconstrucción y reconciliación de plugins instalados. La adopción es explícita y por cuenta; las instalaciones heredadas sin marca mantienen su recorrido anterior. La aceptación completa de dos escritorios y algunos adaptadores siguen pendientes. Configurar épocas de escritura tiene efectos irreversibles de servidor explicados en la revisión de migración.</p><p>V3 añade catálogo, equipos, integraciones, recursos, overlays y paquetes según capacidades. Los metadatos del catálogo no sustituyen firmas de plugins. Importar plantillas/perfiles pasa por el diario del propietario; revisa enabled al aplicar/importar perfil. Aplicar paquetes registra pasos interrumpidos sin repetirlos automáticamente. Las lecturas mediante relay Cloud no equivalen a autoridad de mutación por colaboración directa.</p><h2 id="expected-result-and-recovery" tabindex="-1">Resultado esperado y recuperación <a class="header-anchor" href="#expected-result-and-recovery" aria-label="Permalink to &quot;Resultado esperado y recuperación {#expected-result-and-recovery}&quot;">​</a></h2><p>Los cambios conservan límites de identidad, revisión y autorización. Changes de Automations es local; Variables revisadas usa métodos tipados nativos reales sin sincronizar valores crudos. Changes de Overlays no está integrado. Ante conflicto, compara base/local/Cloud reciente; ante confirmación incierta, resuelve la intención retenida. Un error HTTP reintentable no autoriza repetir mutaciones. <a href="./collaboration.html">Colaboración</a> explica la autoridad del host activo.</p><h2 id="operational-details" tabindex="-1">Detalles de operación <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalles de operación {#operational-details}&quot;">​</a></h2><p><code>TIKTOOLS_CLOUD_ORIGIN</code> usa runtime → valor compilado → default en debug, pero compilado → default en release: release ignora overrides runtime. Vacío, <code>off</code>, <code>none</code> deshabilitan solo en la capa aplicable. Admite origen HTTPS sin credenciales/ruta/query/fragmento; HTTP solo loopback explícito. Debug aislado: <code>TIKTOOLS_CLOUD_ORIGIN=http://127.0.0.1:8787 bun run start</code>; release: <code>TIKTOOLS_CLOUD_ORIGIN=https://cloud.example bun scripts/task.ts rust build -p tiktools-desktop --release --locked</code>. No restaura identidad de otro origen: revisa origen/cuenta antes de autenticar. Un default compilado no prueba disponibilidad del servicio.</p><p>Sigue <a href="./../user/cloud/changes.html#operational-details">migración y recuperación por modo</a>. Coordina dispositivos antes de política irreversible de época, conserva conteos/resultados y consulta estado tras barrera ambigua; no la repitas para averiguar si ocurrió. La recuperación congela entradas y revisión aprobadas; una revisión caducada se reconstruye antes de reanudar, y reanudar no envía escritura Cloud.</p>`,16)])])}const m=a(r,[["render",n]]);export{h as __pageData,m as default};
